#!/usr/bin/env node
// Bundles every adapter's fixtures/*.html into a fixtures.generated.ts next
// to it, so the same fixtures load under wrangler and under vitest without
// loader tricks. `--check` fails if the generated file is stale.
import { readdirSync, readFileSync, writeFileSync, existsSync, statSync } from 'node:fs';
import { join } from 'node:path';

const check = process.argv.includes('--check');
const adaptersDir = new URL('../src/adapters/', import.meta.url).pathname;
let stale = 0;

for (const name of readdirSync(adaptersDir)) {
  const dir = join(adaptersDir, name);
  const fixtures = join(dir, 'fixtures');
  if (!statSync(dir).isDirectory() || !existsSync(fixtures)) continue;
  const files = readdirSync(fixtures).filter((f) => f.endsWith('.html')).sort();
  const entries = files.map((f) => `  ${JSON.stringify(f)}: ${JSON.stringify(readFileSync(join(fixtures, f), 'utf8'))},`).join('\n');
  const out = `// Generated by scripts/bundle-fixtures.mjs from fixtures/*.html. Do not edit.\n// These fixtures are SYNTHETIC: hand-written to match the selectors the\n// adapter expects, not captured from the live site.\nexport const fixtures: Record<string, string> = {\n${entries}\n};\n`;
  const target = join(dir, 'fixtures.generated.ts');
  const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
  if (current !== out) {
    if (check) { console.error(`stale: ${target}`); stale++; }
    else { writeFileSync(target, out); console.log(`wrote ${target} (${files.length} files)`); }
  }
}
if (check) { console.log(stale ? `${stale} stale fixture bundle(s); run pnpm fixtures:build` : 'fixture bundles current'); process.exit(stale ? 1 : 0); }
